-- A foreign key is checked after the row's index entries: an oversized key whose foreign
-- key has no parent is `54000`, not `23503`.
-- @setup
CREATE TABLE p (id int PRIMARY KEY);
CREATE TABLE c (a text, p int REFERENCES p(id));
CREATE INDEX c_i ON c (a);
-- @test
-- @expect-error: the index row before the foreign key
-- @expect-message
-- @profile-lock
INSERT INTO c VALUES ('', 99);
